#!/usr/bin/env python3
"""ARC-PATH-RESOLUTION133, Python standard library reproducer.
To examine the full original readable source: python THISFILE --show-source
The embedded zlib-compressed source SHA256 is verified before execution.
This is source bundling, not a cryptographic evidence of theorem correctness.
"""
import base64,hashlib,sys,zlib
BODY=''
src=zlib.decompress(base64.b64decode(BODY))
assert hashlib.sha256(src).hexdigest()=='cf98159085f5dc2e1c79860870de388ad9bb57f3f82b19d7c6803a147040ab7a'
if '--show-source' in sys.argv:
    sys.stdout.buffer.write(src)
else:
    exec(compile(src,'ARC_PATH_RESOLUTION133_full_source.py','exec'), {'__name__':'__main__'})
